<script setup>
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {Table,Drawer,Dropdown,Menu,MenuItem,message} from 'ant-design-vue'
import {api,can,getToken} from '../api'
import {confirmAction,dateTime} from '../ui'
import {Plus,MoreHorizontal,Search} from '../icons'
import ReportWizard from '../components/ReportWizard.vue'
import TemplateEditor from '../components/TemplateEditor.vue'
import ReportEditor from '../components/ReportEditor.vue'
import '../report-authoring.css'
const route=useRoute(),router=useRouter(),reports=ref([]),templates=ref([]),query=ref(''),filter=ref('active'),error=ref(''),dirty=ref(false),page=ref(1),loading=ref(false),showVersions=ref(false),trash=ref(false),templateBusy=ref(false),versionTarget=ref(null),preview=ref(null)
const area=computed(()=>route.path.startsWith('/report-templates')?'templates':'reports'),mode=computed(()=>route.path.endsWith('/new')?'new':route.params.id?'edit':'list')
const stateNames={draft:'草稿',in_review:'待审阅',finalized:'已定稿',archived:'已归档'},jobNames={queued:'排队中',generating:'生成与核验中',completed:'生成完成',draft:'正文已保存',needs_review:'待审阅',failed:'生成失败',interrupted:'生成中断',cancelled:'已取消',legacy:'历史记录'},templateNames={published:'已发布',draft:'模板草稿',disabled:'已停用',deleted:'已删除'}
const filtered=computed(()=>reports.value.filter(r=>(!query.value||(r.title+' '+r.template_name+' '+r.knowledge_base_name).toLowerCase().includes(query.value.toLowerCase()))&&(filter.value==='all'||filter.value==='active'&&r.document_state!=='archived'||r.document_state===filter.value)))
function familyId(t){const all=new Map(templates.value.map(row=>[row.id,row])),seen=new Set();while(t.parent_id&&all.has(t.parent_id)&&!seen.has(t.id)){seen.add(t.id);t=all.get(t.parent_id)}return t.family_id||t.parent_id||t.id}
const templateRows=computed(()=>{const rows=templates.value.filter(t=>!query.value||(t.name+' '+t.description+' '+t.version).toLowerCase().includes(query.value.toLowerCase()));if(showVersions.value||trash.value)return rows;const seen=new Set();return rows.filter(t=>{const id=familyId(t);if(seen.has(id))return false;seen.add(id);return true})})
const versions=computed(()=>versionTarget.value?templates.value.filter(t=>familyId(t)===familyId(versionTarget.value)):[])
const reportColumns=[{title:'报告名称',key:'title',width:280},{title:'模板 / 知识库',key:'scope',width:210},{title:'文稿状态',key:'state',width:100},{title:'更新时间',key:'time',width:170},{title:'操作',key:'actions',width:160}]
const templateColumns=[{title:'模板名称',key:'title',width:300},{title:'版本',dataIndex:'version',width:90},{title:'状态',key:'state',width:100},{title:'适用范围',key:'scope',width:140},{title:'操作',key:'actions',width:220}]
let loadId=0
async function load(){const id=++loadId;loading.value=true;error.value='';try{const [r,t]=await Promise.all([api('/api/report-tasks'),api('/api/templates'+(area.value==='templates'&&trash.value?'?deleted=true':''))]);if(id===loadId){reports.value=r;templates.value=t}}catch(e){if(id===loadId)error.value=e.message}finally{if(id===loadId)loading.value=false}}
onMounted(async()=>{if(route.query.task){router.replace('/reports/'+Number(route.query.task));return}await load()})
watch(()=>route.fullPath,()=>{dirty.value=false;query.value='';page.value=1;preview.value=null;versionTarget.value=null;if(mode.value==='list')load()})
watch([query,filter],()=>page.value=1)
watch(trash,()=>{templates.value=[];query.value='';versionTarget.value=null;load()})
async function guard(){return !getToken()||!dirty.value||await confirmAction('尚未保存的修改会丢失。建议先保存，再离开页面。',{title:'离开当前页面？',okText:'离开页面'})}
onBeforeRouteLeave(guard);onBeforeRouteUpdate(guard)
function beforeUnload(event){if(dirty.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload));onUnmounted(()=>window.removeEventListener('beforeunload',beforeUnload))
async function setTemplateState(t,state){templateBusy.value=true;try{await api('/api/report-templates/'+t.id+'/lifecycle?state='+state,{method:'PATCH'});message.success(state==='published'?'模板已发布':'模板已停用');await load()}catch(e){error.value=e.message}finally{templateBusy.value=false}}
async function askDelete(t){if(!await confirmAction('仅将“'+(t.name||'历史未命名模板')+' · '+t.version+'”移入回收站，不删除其他版本；已有报告、定稿和原文件保留。可在回收站恢复。',{title:'删除这个模板版本？',danger:true,okText:'确认移入回收站'}))return;templateBusy.value=true;try{const result=await api('/api/report-templates/'+t.id,{method:'DELETE'});message.success(result.message);versionTarget.value=null;await load()}catch(e){error.value=e.message}finally{templateBusy.value=false}}
async function restoreTemplate(t){templateBusy.value=true;try{const result=await api('/api/report-templates/'+t.id+'/restore',{method:'POST'});message.success(result.message);await load()}catch(e){error.value=e.message}finally{templateBusy.value=false}}
async function archive(r){if(!await confirmAction('归档后保留正文和所有定稿，不再显示在默认列表；可在归档筛选中找到并创建可编辑修订。',{title:'归档“'+r.title+'”？',okText:'确认归档'}))return;try{await api('/api/reports/'+r.id,{method:'PATCH',body:JSON.stringify({expected_revision:r.revision,document_state:'archived'})});message.success('报告已归档');await load()}catch(e){error.value=e.message}}
async function showPreview(t){try{preview.value=await api('/api/report-templates/'+t.id)}catch(e){error.value=e.message}}
</script>
<template><div>
 <ReportWizard v-if="area==='reports'&&mode==='new'" :key="route.fullPath" @dirty="dirty=$event"/>
 <ReportEditor v-else-if="area==='reports'&&mode==='edit'" :key="route.params.id" :report-id="Number(route.params.id)" @dirty="dirty=$event"/>
 <TemplateEditor v-else-if="area==='templates'&&mode!=='list'" :key="route.fullPath" :template-id="Number(route.params.id)||undefined" @dirty="dirty=$event"/>
 <section v-else class="page-stack">
  <div class="page-intro"><div><h2>{{area==='reports'?'报告中心':'模板库'}}</h2><p>{{area==='reports'?'继续编写、审阅并定稿。机器提供证据，最终决定由你做出。':'选择适用结构开始报告，按版本维护模板。'}}</p></div><button v-if="area==='reports'" class="primary-button" @click="router.push('/reports/new')"><Plus :size="16"/>新建报告</button><button v-else-if="can('templates.manage')" class="primary-button" @click="router.push('/report-templates/new')"><Plus :size="16"/>创建模板</button></div>
  <div v-if="error" class="error-banner" role="alert">{{error}} <button class="text-button" @click="load">重新加载</button></div>
  <p v-if="area==='templates'&&trash" class="warning-banner">回收站保留原文件和历史版本。恢复后为停用状态，发布后才能用于新报告。</p>
  <section class="card"><div class="filter-bar"><div class="report-search"><Search :size="16"/><input v-model="query" class="input" :placeholder="area==='reports'?'搜索报告、模板或知识库':'搜索模板名称、用途或版本'" aria-label="搜索报告或模板"/></div><select v-if="area==='reports'" v-model="filter" class="select" aria-label="报告状态筛选"><option value="active">未归档报告</option><option value="all">全部报告</option><option v-for="(label,id) in stateNames" :key="id" :value="id">{{label}}</option></select><label v-if="area==='templates'&&!trash" class="check-line"><input v-model="showVersions" type="checkbox"/>全部版本</label><label v-if="area==='templates'&&can('templates.manage')" class="check-line"><input v-model="trash" type="checkbox" :disabled="templateBusy"/>回收站</label><span class="muted">共 {{area==='reports'?filtered.length:templateRows.length}} 条</span><button class="text-button" @click="load">刷新</button></div>
   <Table v-if="area==='reports'" :columns="reportColumns" :data-source="filtered" row-key="id" :loading="loading" :scroll="{x:920}" :pagination="{pageSize:12,hideOnSinglePage:true,showSizeChanger:false}" size="middle"><template #bodyCell="{column,record:r}"><template v-if="column.key==='title'"><router-link :to="'/reports/'+r.id" class="table-title">{{r.title}}</router-link><small class="table-description">{{jobNames[r.status]||r.status}}<template v-if="['queued','generating'].includes(r.status)"> · {{r.progress}}%</template></small></template><template v-else-if="column.key==='scope'"><span>{{r.template_name||'历史模板'}}</span><small class="table-description">{{r.knowledge_base_name}}</small></template><template v-else-if="column.key==='state'"><span class="badge" :class="r.document_state==='finalized'?'green':r.document_state==='archived'?'':'blue'">{{stateNames[r.document_state]||'草稿'}}</span></template><template v-else-if="column.key==='time'"><span class="muted">{{dateTime(r.updated_at||r.created_at)}}</span></template><template v-else-if="column.key==='actions'"><div class="table-actions"><router-link :to="'/reports/'+r.id" class="text-button">{{r.document_state==='finalized'?'查看定稿':r.document_state==='archived'?'查看归档':'继续编写'}}</router-link><Dropdown v-if="r.document_state!=='archived'&&!['queued','generating'].includes(r.status)" :trigger="['click']"><button class="icon-button" :aria-label="'更多报告操作 '+r.title"><MoreHorizontal :size="18"/></button><template #overlay><Menu><MenuItem key="archive" @click="archive(r)">归档报告</MenuItem></Menu></template></Dropdown></div></template></template><template #emptyText><div class="empty"><h3>{{query?'没有匹配报告':'还没有报告'}}</h3><p>选择已发布模板与授权知识库，生成第一份草稿。</p><button class="primary-button" @click="router.push('/reports/new')">新建报告</button></div></template></Table>
   <Table v-else :columns="templateColumns" :data-source="templateRows" row-key="id" :loading="loading" :scroll="{x:850}" :pagination="{pageSize:10,hideOnSinglePage:true,showSizeChanger:false}" size="middle"><template #bodyCell="{column,record:t}"><template v-if="column.key==='title'"><button v-if="!trash" class="template-title" @click="showPreview(t)">{{t.name||'历史未命名模板'}}</button><strong v-else class="table-title">{{t.name||'历史未命名模板'}}</strong><small class="table-description">{{t.blueprint?.purpose||t.description||'未填写用途说明'}}</small></template><template v-else-if="column.key==='state'"><span class="badge" :class="t.lifecycle==='published'?'green':t.lifecycle==='deleted'?'red':'amber'">{{templateNames[t.lifecycle]}}</span></template><template v-else-if="column.key==='scope'">{{t.knowledge_base_ids.length?'限定知识库':'通用模板'}}<small class="table-description">{{t.sections.length}}节 · {{t.import_id?'Word导入':'结构化模板'}}</small></template><template v-else-if="column.key==='actions'"><div class="table-actions"><template v-if="!trash"><router-link v-if="t.lifecycle==='published'" :to="'/reports/new?template='+t.id" class="text-button">新建报告</router-link><button v-else class="text-button" @click="showPreview(t)">预览结构</button><button class="text-button" @click="versionTarget=t">版本</button><Dropdown v-if="can('templates.manage')" :trigger="['click']"><button class="icon-button" :aria-label="'管理模板 '+t.name"><MoreHorizontal :size="18"/></button><template #overlay><Menu><MenuItem key="edit" @click="router.push('/report-templates/'+t.id+'/edit')">编辑新版本</MenuItem><MenuItem key="publish" :disabled="templateBusy" @click="setTemplateState(t,t.lifecycle==='published'?'disabled':'published')">{{t.lifecycle==='published'?'停用':'发布'}}</MenuItem><MenuItem key="delete" danger :disabled="templateBusy" @click="askDelete(t)">删除此版本</MenuItem></Menu></template></Dropdown></template><button v-else-if="can('templates.manage')" class="text-button" :disabled="templateBusy" @click="restoreTemplate(t)">恢复为停用模板</button></div></template></template><template #emptyText><div class="empty">{{trash?'回收站中没有匹配的模板版本。':'暂无匹配模板，请调整搜索或联系管理员发布。'}}</div></template></Table>
  </section>
 </section>
 <Drawer :open="!!versionTarget" title="模板版本" width="min(520px,100vw)" @close="versionTarget=null"><p class="muted">{{versionTarget?.name}} · 只展示当前列表可访问的版本，删除版本请到回收站查看。</p><article v-for="t in versions" :key="t.id" class="version-row"><div class="toolbar"><strong>{{t.version}}</strong><span class="badge" :class="t.lifecycle==='published'?'green':'amber'">{{templateNames[t.lifecycle]}}</span></div><p class="muted">{{dateTime(t.created_at)}}</p><div class="toolbar"><button class="text-button" @click="showPreview(t)">预览结构</button><router-link v-if="t.lifecycle==='published'" :to="'/reports/new?template='+t.id" class="text-button">新建报告</router-link><router-link v-if="can('templates.manage')" :to="'/report-templates/'+t.id+'/edit'" class="text-button">编辑新版本</router-link><button v-if="can('templates.manage')" class="text-button danger" @click="askDelete(t)">删除此版本</button></div></article></Drawer>
 <Drawer :open="!!preview" title="模板结构预览" width="min(640px,100vw)" @close="preview=null"><template v-if="preview"><h3>{{preview.name}} <span class="badge">{{preview.version}}</span></h3><p class="muted">{{preview.blueprint.purpose||preview.description||'未填写用途说明'}}</p><ol class="template-outline"><li v-for="(s,i) in preview.blueprint.sections" :key="i" :style="{marginLeft:(s.level-1)*12+'px'}"><strong>{{s.title}}</strong><small>{{({fact:'事实正文',analysis:'分析',recommendation:'建议',fixed:'固定文字',container:'目录容器'})[s.kind]||'事实正文'}} · {{s.required?'必需章节':'可选章节'}}</small><p>{{s.fixed_content||s.instructions||'按知识库证据生成'}}</p></li></ol><p class="muted">这是结构预览，不是生成后的报告。固定文字和业务字段仍需人工核对。</p><router-link v-if="preview.lifecycle==='published'" :to="'/reports/new?template='+preview.id" class="primary-button">用此版本新建报告</router-link></template></Drawer>
</div></template>
<style scoped>.report-search{display:flex;align-items:center;position:relative;width:280px}.report-search>.ui-icon{position:absolute;left:10px;color:#99a1ae}.report-search .input{padding-left:34px;width:100%}.template-title{border:0;background:none;padding:0;color:#1f2329;text-align:left;font-size:13px;font-weight:500}.template-title:hover{color:#1677ff}.table-description{max-width:300px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.version-row{padding:18px 0;border-bottom:1px solid #edf0f5}.template-outline{padding-left:20px}.template-outline li{margin-top:18px;font-size:13px}.template-outline small{display:block;color:#8a929f;font-size:11px;margin-top:4px}.template-outline p{color:#626b79;font-size:12px;line-height:1.8}@media(max-width:767px){.report-search{width:100%}}</style>
